import torch, json
E=W('model.embed_tokens.weight'); g=W('model.embedding_norm.weight')
U=E*g  # effective unembed
Un=U/U.norm(dim=1,keepdim=True)
def ids(words):
    out=[]
    for w in words:
        t=encode(w)
        if len(t)==1: out.append(t[0])
    return out
groups={
 'month':[' '+m for m in 'January February March April May June July August September October November December'.split()],
 'weekday':[' '+d for d in 'Monday Tuesday Wednesday Thursday Friday Saturday Sunday'.split()],
 'color':[' '+c for c in 'red blue green yellow purple orange black white pink brown gray'.split()],
 'digit':[' '+str(i) for i in range(10)],
 'roman':[' '+r for r in 'II III IV VI VII VIII IX XI XII'.split()],
 'planet':[' '+p for p in 'Mercury Venus Mars Jupiter Saturn Uranus Neptune'.split()],
 'element':[' '+p for p in 'hydrogen oxygen carbon nitrogen helium sodium iron'.split()],
 'french':[' '+p for p in 'le la les des une est dans pour avec'.split()],
 'animal':[' '+p for p in 'dog cat horse cow sheep lion tiger bird fish'.split()],
}
gid={k:ids(v) for k,v in groups.items()}
print({k:len(v) for k,v in gid.items()})
dirs={}
for k,v in gid.items():
    d=Un[v].mean(0); dirs[k]=d/d.norm()
D=torch.stack([dirs[k] for k in groups])
res={}
for L in range(30):
    W2=W(f'model.layers.{L}.feed_forward.w2.weight')  # 2048 x 10752
    C=W2/W2.norm(dim=0,keepdim=True)
    cos=D@C  # groups x units
    for i,k in enumerate(groups):
        a=cos[i].abs(); v,ix=a.topk(3)
        res.setdefault(k,[]).append((L,[(int(j),round(float(cos[i,j]),3)) for j in ix]))
for k in groups:
    best=sorted(res[k],key=lambda x:-abs(x[1][0][1]))[:5]
    print(k,best)
